// Room codes: 5 characters without look-alikes (no I, L, O, 0, 1), generated by the server.
import { isRoomCode, SERVER_ROOM_CODE_ALPHABET } from './protocol.ts';

export const ROOM_CODE_ALPHABET = SERVER_ROOM_CODE_ALPHABET;
export const ROOM_CODE_LENGTH = 5;

/** Returns an integer in [0, max). The server passes crypto.randomInt. */
export type RandomInt = (max: number) => number;

export function createRoomCode(randomInt: RandomInt): string {
  let code = '';
  for (let i = 0; i < ROOM_CODE_LENGTH; i++) code += ROOM_CODE_ALPHABET[randomInt(ROOM_CODE_ALPHABET.length)];
  return code;
}

/** Normalises what a player typed (trim, upper case); returns null unless it is a well-formed code. */
export function parseRoomCode(input: string): string | null {
  const code = input.trim().toUpperCase();
  return isRoomCode(code) ? code : null;
}
